$id=(int)($_GET['order_id']??0);$order=null;if($con&&$con!==false&&$id>0){$st=$con->prepare('SELECT o.*,c.name car_name,c.images car_images FROM orders o LEFT JOIN cars c ON c.id=o.car_id WHERE o.id=? AND o.user_id=? LIMIT 1');if($st){$st->bind_param('ii',$id,$_SESSION['user_id']);$st->execute();$order=$st->get_result()->fetch_assoc();$st->close();}}
